cones1 :: Int -> Int
cones1 x = n*n - x
  where
    n = ceiling $ sqrt $ (fromIntegral x)


cones2 :: Int -> Int
cones2 1 = 7
cones2 2 = 6
cones2 3 = 5
cones2 4 = 4
cones2 n 
  | mn==0 = 0
  | otherwise = 4 - mn
  where
    mn = mod n 4


cones3 :: Int -> Int
cones3 x
  | even n = (n+1)*(n+1) - x - 1
  | n*n == x = (n+2)*(n+2) - x - 1
  | otherwise = n*n - x - 1
  where
    n = ceiling $ sqrt $ (fromIntegral x)


